<section class="section narrow"><span class="kicker dark">TU SELECCIÓN</span><h1>CARRITO</h1><?php if(!$photos):?><div class="empty"><h2>Tu carrito está vacío</h2><a class="primary" href="<?=url()?>">VER FOTOS</a></div><?php else:$total=0;foreach($photos as $p):$total+=(int)$p['price'];?><article class="line"><img src="<?=url($p['preview_path'])?>"><div><h3><?=htmlspecialchars($p['title'])?></h3><small><?=htmlspecialchars($p['event_name'])?></small></div><strong><?=money((int)$p['price'])?></strong><form method="post" action="<?=url('carrito/eliminar')?>"><input type="hidden" name="_token" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$p['id']?>"><button>Quitar</button></form></article><?php endforeach;?><div class="total"><span>Total</span><strong><?=money($total)?></strong></div><a class="primary" href="<?=url('checkout')?>">CONTINUAR AL PAGO →</a><?php endif;?></section>

